    ('DC-GOT', 'GYP-13-1200X2400', '12', '0'),
    ('DC-GOT', 'CEM-25', '300', '0'),
    ('DC-GOT', 'ISO-100-1200', '100', '0'),
    ('DC-GOT', 'TOOL-LASER', '25', '0'),
    ('DC-MAL', 'TRB-45X95-3600', '18', '0'),
    ('DC-MAL', 'TRB-45X145-4800', '18', '0'),
    ('DC-MAL', 'GYP-13-1200X2400', '80', '0'),
    ('DC-MAL', 'CEM-25', '300', '0'),
